import { test, expect } from '@playwright/test';

test.describe('Invalid Coupon Code Error Message', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example-ecommerce.com/checkout');
    // Wait for the page to load
    await page.waitForLoadState('networkidle');
  });

  test('should display error message when applying invalid coupon code', async ({ page }) => {
    // Find and fill the coupon code input field
    const couponInput = page.getByLabel('Coupon Code');
    await couponInput.fill('INVALID123');

    // Click the apply coupon button
    const applyButton = page.getByRole('button', { name: /apply coupon/i });
    await applyButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/invalid coupon code/i);
    await expect(errorMessage).toBeVisible();

    // Verify error message has appropriate styling (e.g., red color or error class)
    await expect(errorMessage).toHaveClass(/error|invalid/);
  });

  test('should clear error message when user corrects the coupon code', async ({ page }) => {
    // Apply invalid coupon code first
    const couponInput = page.getByLabel('Coupon Code');
    await couponInput.fill('INVALID123');

    const applyButton = page.getByRole('button', { name: /apply coupon/i });
    await applyButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/invalid coupon code/i);
    await expect(errorMessage).toBeVisible();

    // Clear the input and enter a valid coupon code
    await couponInput.clear();
    await couponInput.fill('VALID50');
    await applyButton.click();

    // Verify error message is no longer visible
    await expect(errorMessage).not.toBeVisible();

    // Verify success message or discount is applied
    const successMessage = page.getByText(/coupon applied|discount applied/i);
    await expect(successMessage).toBeVisible();
  });

  test('should display specific error message for expired coupon code', async ({ page }) => {
    // Apply an expired coupon code
    const couponInput = page.getByLabel('Coupon Code');
    await couponInput.fill('EXPIRED2020');

    const applyButton = page.getByRole('button', { name: /apply coupon/i });
    await applyButton.click();

    // Verify specific error message for expired coupon
    const expiredErrorMessage = page.getByText(/coupon code has expired|this coupon is no longer valid/i);
    await expect(expiredErrorMessage).toBeVisible();
  });

  test('should display error message for coupon code with insufficient cart value', async ({ page }) => {
    // Apply a coupon that requires minimum cart value
    const couponInput = page.getByLabel('Coupon Code');
    await couponInput.fill('MINPURCHASE100');

    const applyButton = page.getByRole('button', { name: /apply coupon/i });
    await applyButton.click();

    // Verify error message about minimum purchase requirement
    const minPurchaseError = page.getByText(/minimum purchase|cart value must be/i);
    await expect(minPurchaseError).toBeVisible();
  });

  test('should maintain error message visibility until user takes action', async ({ page }) => {
    // Apply invalid coupon code
    const couponInput = page.getByLabel('Coupon Code');
    await couponInput.fill('BADCODE');

    const applyButton = page.getByRole('button', { name: /apply coupon/i });
    await applyButton.click();

    // Verify error message is visible
    const errorMessage = page.getByText(/invalid coupon code/i);
    await expect(errorMessage).toBeVisible();

    // Wait a moment to ensure error persists
    await page.waitForTimeout(2000);

    // Verify error message is still visible
    await expect(errorMessage).toBeVisible();

    // User clears the field
    await couponInput.clear();

    // Error message should be cleared or hidden
    await expect(errorMessage).not.toBeVisible();
  });
});
